function keyboard(id,words=[]){let rows=(layouts[id]||['QWERTYUIOP','ASDFGHJKL','ZXCVBNM']).map(r=>Array.from(r));let present=new Set(rows.flat());const chars=[...new Set(Array.from((extras[id]||'')+words.map(w=>w.answer).join('')).filter(c=>!present.has(c)))];for(let i=0;i<chars.length;i+=12)rows.push(chars.slice(i,i+12));return rows;}
